;The Empire Strikes Back (Atari, 1985) - hardware map, RAM variables and equates
;of the sound board's 6809, for esb_sound_rom.asm.
;Names carried over from the Star Wars source are Atari's identifiers ('.' -> '_'
;and '$' -> 'S_'), given to the address or value the same code uses here.
;Descriptions in upper case are Atari's comments on the Star Wars definitions;
;those in lower case were written for the Star Wars or for this disassembly.
;Generated by disasm/emit_defines.py; every symbol the listings use is here.

;----------------------------------[ Memory map ]----------------------------------
.alias SoundOut          $00      ;Through $07FF, write: byte to the main CPU.
.alias SoundIn           $800     ;Through $0FFF, read: byte from the main CPU.
.alias RiotRam           $1000    ;Through $107F. 6532 RAM: the direct page and the stack.
.alias RiotIo            $1080    ;Through $109F. 6532 ports and timer.
.alias Pokeys            $1800    ;Through $183F. Four POKEYs, registers interleaved.
.alias SoundRam          $2000    ;Through $27FF. Program RAM.
.alias SoundRomLow       $4000    ;Through $7FFF (esb_sound_rom.asm).
.alias SoundRomHigh      $C000    ;Through $FFFF (esb_sound_rom.asm); the 6809 vectors are at $FFF2.

;----------------------------------[ Hardware registers ]----------------------------------
.alias SOUT              $00      ;Write: byte to the main CPU; sets the sound flag. The main loop writes PBXS_OK here as its watchdog.
.alias SIN               $800     ;Read: byte from the main CPU; resets the main flag.
.alias DPRAMZ            $1080    ;End of the 6532 RAM (limit of INIT's clear loop).
.alias PAD               $1080    ;6532 port A data. D0 /WS and D1 /RS speech strobes, D2 speech /RDY (in), D3 /FM, D4 self test switch (in, 1=off), D5 5220 power (1=off), D6 sound flag (in), D7 main flag (in).
.alias TESTSW            $1080    ;Port with the self test switch (bit TESTBT of PAD).
.alias PADD              $1081    ;6532 port A direction; INIT writes $2B (D0, D1, D3, D5 outputs).
.alias PBD               $1082    ;6532 port B data: the speech chip's data bus.
.alias PBDD              $1083    ;6532 port B direction; INIT writes $FF.
.alias RIF               $1085    ;Read: interrupt flags, D7 timer, D6 PA7 (the main CPU has sent a byte); reading resets the PA7 flag.
.alias EIPED             $1087    ;Write: enable the PA7 interrupt, positive edge detect; INIT's choice.
.alias E1024T            $109F    ;Write: timer, 1024 clocks per count, timer interrupt enabled; INIT and the IRQ write 6 for the 4 ms interrupt.
.alias P_BASE            $1800    ;Base of the four POKEYs (chips 0-3 in SNDCMN's map; registers 0-7 of each at $1800, 8-F at $1820).
.alias P_SND             $1800    ;8 HARDWARE SOUND CHANNELS
.alias PKFL3             $1810    ;Music voice 3, frequency low: AUDF1 of chip 2.
.alias PKFH3             $1812    ;Music voice 3, frequency high: AUDF2 of chip 2.
.alias PKFL4             $1814    ;Music voice 4, frequency low: AUDF3 of chip 2. Voices 5-8 share it until reconfigured.
.alias PKFH4             $1816    ;Music voice 4, frequency high: AUDF4 of chip 2.
.alias PKFL1             $1818    ;Music voice 1, frequency low: AUDF1 of chip 3.
.alias PKFH1             $181A    ;Music voice 1, frequency high: AUDF2 of chip 3.
.alias PKFL2             $181C    ;Music voice 2, frequency low: AUDF3 of chip 3.
.alias PKFH2             $181E    ;Music voice 2, frequency high: AUDF4 of chip 3.
.alias P_ACT1            $1820    ;AUDIO CONTROL,1(AUDCTL)
.alias P_SNDZ_1820       $1820    ;SNDAUX's P.SNDZ: end of the AUDF/AUDC registers of all four chips (limit of INIT's clear loop).
.alias P_BGN1            $1827    ;BEGIN POKEY1=CYCLE 0 TO 3
.alias P_ACT2            $1828    ;AUDIO CONTROL,2
.alias P_BGN2            $182F    ;BEGIN POKEY2 (SKCTL)
.alias PKC1              $1830    ;AUDCTL of chip 2: $78 joins its channels in pairs for 16-bit voices, 0 leaves all four apart (dynamic reconfiguration).
.alias P_ACT3            $1830    ;AUDCTL of chip 2, cleared by INIT.
.alias PKI1              $1837    ;SKCTL of chip 2: ISND writes 0, then 3, to initialize the chip.
.alias P_BGN3            $1837    ;SKCTL of chip 2: INIT writes 0, then 7.
.alias PKC2              $1838    ;AUDCTL of chip 3: $78 joins its channels in pairs for 16-bit voices, 0 leaves all four apart.
.alias P_ACT4            $1838    ;AUDCTL of chip 3, cleared by INIT.
.alias PKI2              $183F    ;SKCTL of chip 3: ISND writes 0, then 3, to initialize the chip.
.alias P_BGN4            $183F    ;SKCTL of chip 3: INIT writes 0, then 7.

;----------------------------------[ 6532 RAM ]----------------------------------
.alias S_GARBG           $1000    ;GARBAGE TEST
.alias S_INTHI           $1009    ;HI BYTE OF INT COUNTER, 1 SECOND COUNTER
.alias S_INTCT           $100A    ;PSUEDO INT COUNTER, EVERY 4 MILLS
.alias SYNC              $100B    ;SYNC UP THE MAINLINE TO A 4 MS RATE
.alias CMDTOP            $100C    ;DISP TO TOP OF GENERAL COMMAND BUFFER,FIFO
.alias CMDBTM            $100D    ;DISP TO BOTTOM(CATCHING UP) OF BUFFER
.alias DG_SEQ            $100E    ;SEQUENCE THRU EACH ITEM, DIAGNOSTIC
.alias TESTON            $100F    ;0->OFF, 1->ON (RIGHT PLACE TO PUT THIS?)
.alias FASV              $1010    ;FREQUENCY ADJUST MSB SAVE (COMMON POKEY TEMP)
.alias VIU               $1011    ;FLAGS TO TELL WHICH VOICES ARE IN USE
.alias DREF              $1012    ;Dynamic reconfiguration flag: 0 = normal (16-bit voices), 1 = every voice 8 bits on its VCS_PKD register (RCS sets it, RCN clears it).
.alias SP_BGN            $1013    ;CURRENT SAMPLE POINTER
.alias SP_DLY            $1015    ;INTER-WORD DELAY
.alias SP_DOG            $1016    ;WATCHDOG TIMER
.alias SP_END            $1017    ;END POINTER FOR CURRENT SAMPLE SETS
.alias SP_MES            $1019    ;CURRENT WORD LIST POINTER
.alias SP_NXT            $101B    ;NEXT WORD LIST POINTER AFTER CURRENT IS DONE
.alias SP_QBT            $101D    ;BOTTOM OF SPEECH SENTENCE QUEUE
.alias SP_QTP            $101E    ;TOP OF SPEECH SENTENCE QUEUE
.alias SP_RES            $101F    ;RESET FLAG AND COUNTER
.alias SP_STA            $1020    ;STATUS AND PHASE OF SPEECH ROUTINE

;----------------------------------[ Program RAM ]----------------------------------
.alias CMD               $2020    ;GENERAL COMMAND BUFFER, CIRCULAR FIFO
.alias AU_SHF            $2100    ;BITS FOR USED CHANNELS
.alias AU_BLK            $2101    ;Sound effect channel blocks: AUS_EQ sets of AUS_IZ bytes, one per hardware channel.
.alias VOICE1            $2200    ;POKEY (VOICE 1)
.alias VOICE2            $2219    ;POKEY (VOICE 2)
.alias VOICE3            $2232    ;POKEY (VOICE 3 OR 3A)
.alias VOICE4            $224B    ;POKEY (4 OR VOICE 4A)
.alias VOICE5            $2264    ;Music voice 5 RAM block: priority 2 on voice 4's output.
.alias VOICE6            $227D    ;Music voice 6 RAM block: priority 3 on voice 4's output.
.alias VOICE7            $2296    ;Music voice 7 RAM block: priority 4 on voice 4's output.
.alias VOICE8            $22AF    ;Music voice 8 RAM block: priority 5 on voice 4's output.
.alias SPKQUE            $2300    ;Speech sentence FIFO: 16 word list pointers, indexed by SP_QTP and SP_QBT.

;----------------------------------[ Constants ]----------------------------------
.alias APTR              $02      ;POINTER TO START OF CURRENT AMP. ENVELOPE
.alias AUS_EQ            $10      ;# OF SETS IN THIS SEQUENCE
.alias AUS_IZ            $05      ;SIZE OF SET PER CHANNEL
.alias AUS_PNT           $00      ;POINTER INTO TAUBLK, CHANNEL INFO
.alias AUS_RPT           $03      ;COUNTER FOR REPEATING PHRASES
.alias AUS_SND           $04      ;CURRENT OUTPUT PHRASE VALUE
.alias AUS_TMR           $02      ;TIMER COUNT TO NEXT PHRASE
.alias BT3               $08      ;Data bit 3.
.alias BT5               $20      ;Data bit 5.
.alias DGS_VIB           $03      ;NO VIBRATO FOR 3 DIAGNOSTICS
.alias DPRAM             $1000    ;DPAGE IN 6532 FOR FAST INT PROCESSING
.alias FPTR              $04      ;POINTER TO START OF CURRENT FREQ. ENVELOPE
.alias ODUR              $08      ;CURRENT OUTPUT DURATION REMAINING
.alias OKEY              $0D      ;CURRENT KEY OFFSET
.alias ONOTE             $06      ;CURRENT OUTPUT NOTE COUNT
.alias OPTLL             $14      ;OUTPUT POINTER LOOP SAVE
.alias OPTRET            $17      ;RETURN ADDRESS FROM GOSUB
.alias OPTSV             $12      ;OUTPUT POINTER SUB-PHRASE SAVE
.alias ORATE             $0C      ;NEG OF CURRENT OUTPUT RATE (BIGGER # = SHORTER DUR.)
.alias PBXS_EQ           $53      ;One more than the highest command number (IDAYEA); a command byte above it is dropped.
.alias PBXS_OK           $D3      ;WATCHDOG OK TO MAIN
.alias RAM               $2000    ;Start of program RAM.
.alias RAMZ              $2800    ;End of program RAM (limit of INIT's clear loop).
.alias ROM0              $4000    ;Start of ROM 0 (8K); its first word is the checksum word.
.alias TAS_INC           $03      ;MODIFIES SND FOR SUBSEQUENT PHRASES
.alias TAS_IZ            $04      ;LENGTH OF PHRASE BLOCK
.alias TAS_RPT           $00      ;REPEAT PHRASE N TIMES
.alias TAS_SND           $02      ;STARTING VALUE FOR FIRST PHRASE
.alias TAS_TMR           $01      ;EACH PHRASE LASTS M BEATS
.alias TESTBT            $10      ;Self test switch bit in TESTSW; 0 = on.
.alias VAC               $0E      ;VOICE AMPLITUDE CONTROL BITS
.alias VC1               $01      ;VOICE MASK BITS
.alias VC2               $02      ;Voice 2 mask bit.
.alias VC3               $04      ;Voice 3 mask bit.
.alias VC4               $08      ;Voice 4 mask bit.
.alias VC5               $10      ;Voice 5 mask bit.
.alias VC6               $20      ;Voice 6 mask bit.
.alias VC7               $40      ;Voice 7 mask bit.
.alias VC8               $80      ;Voice 8 mask bit.
.alias VCS_1             $00      ;Offset of voice 1's descriptor in TVC (8 bytes each).
.alias VCS_2             $08      ;Offset of voice 2's descriptor in TVC (8 bytes each).
.alias VCS_3             $10      ;Offset of voice 3's descriptor in TVC (8 bytes each).
.alias VCS_4             $18      ;Offset of voice 4's descriptor in TVC (8 bytes each).
.alias VCS_5             $20      ;Offset of voice 5's descriptor in TVC (8 bytes each).
.alias VCS_6             $28      ;Offset of voice 6's descriptor in TVC (8 bytes each).
.alias VCS_7             $30      ;Offset of voice 7's descriptor in TVC (8 bytes each).
.alias VCS_8             $38      ;Offset of voice 8's descriptor in TVC (8 bytes each).
.alias VCS_BIT           $02      ;Offset in a voice descriptor: the voice's mask bit (VC1-VC8).
.alias VCS_PKD           $06      ;Offset in a voice descriptor: the POKEY register to use instead when dynamically reconfigured.
.alias VCS_PKF           $03      ;Offset in a voice descriptor: the POKEY frequency register it normally uses.
.alias VCS_PRI           $05      ;Offset in a voice descriptor: priority mask, the voices that take its output away when in use.
.alias VLC               $16      ;LOOP COUNTER
.alias VSA               $10      ;VOICE SYNTH. MODE FREQ. ADJUST
.alias VSEQ              $0B      ;VOICE DURATION SEQUENCE #
.alias VSF               $0F      ;VOICE SYNTH. MODE FLAG
.alias VVOL              $0A      ;MEDIAN VOICE VOLUME
